const rpSections=[['overview','Imported pack','layers'],['websites','Website studies','globe'],['resources','Resources & tutorials','code'],['updates','Coverage & updates','grid'],['brief','Original task pack','code']];
const rpSidebar=sidebar;sidebar=function(){return rpSidebar().replace('</nav>','<details open class="nav-level-one reference-navigation"><summary>'+svgIcon('folder')+'<span>Reference Research & Tutorials</span>'+svgIcon('chevron')+'</summary><div>'+rpSections.map(([r,t,i])=>navLeaf('reference-research/'+r,t,i)).join('')+'</div></details></nav>');};
function rpPreview(id){const item=window.REFERENCE_CLONES.find(x=>x.id===id);if(!item)return;myPreview(item.name,'<div class="rp-preview-tools"><span>Separate local HTML · interactive reference reproduction</span><button id="rp-download">Download HTML</button></div><iframe title="'+esc(item.name)+' preview" sandbox="allow-scripts allow-downloads allow-popups" referrerpolicy="no-referrer"></iframe>');document.querySelector('#my-preview iframe').srcdoc=item.html;document.getElementById('rp-download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([item.html],{type:'text/html'}));a.download=item.id+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};}
function rpPage(section){const label=rpSections.find(x=>x[0]===section)?.[1]||'Imported pack';const rs=window.REFERENCE_PACK.resources,sites=window.REFERENCE_CLONES;document.getElementById('main').innerHTML='<section class="my-library rp-library"><div class="my-kicker">REFERENCE RESEARCH / SEPTEMBER 2026</div><div class="my-title"><div><h1>'+esc(label)+'</h1><p>The supplied website studies, tools and learning resources. A separate collection below your personal library.</p></div><span class="my-badge">Imported task pack</span></div><nav class="my-tabs">'+rpSections.map(([r,t,i])=>'<a href="#/reference-research/'+r+'" '+(r===section?'aria-current="page"':'')+'>'+svgIcon(i)+t+'</a>').join('')+'</nav><div id="rp-content"></div></section>';
const c=document.getElementById('rp-content');
const siteCards=()=>'<div class="my-grid rp-sites">'+sites.map((s,i)=>'<article class="my-card"><div class="rp-number">0'+(i+1)+'</div><small>SEPARATE HTML PROJECT</small><h2>'+esc(s.name)+'</h2><p>'+esc(s.summary)+'</p><div class="my-actions"><button data-rp-preview="'+s.id+'">Explore local HTML '+svgIcon('arrow')+'</button><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">Source ↗</a></div></article>').join('')+'</div>';
if(section==='overview'||!section){c.innerHTML='<div class="my-stats"><a href="#/reference-research/websites"><strong>'+sites.length+'</strong><span>Website studies</span>'+svgIcon('globe')+'</a><a href="#/reference-research/resources"><strong>'+rs.length+'</strong><span>Imported resources</span>'+svgIcon('code')+'</a><a href="#/reference-research/resources"><strong>'+new Set(rs.map(x=>x.category)).size+'</strong><span>Resource categories</span>'+svgIcon('folder')+'</a><a href="#/reference-research/updates"><strong>02</strong><span>Source documents</span>'+svgIcon('layers')+'</a></div>'+siteCards();}
else if(section==='websites'){c.innerHTML=siteCards();}
else if(section==='brief'){c.innerHTML='<div class="rp-notice"><h2>Original supplied brief</h2><p>Preserved as reference material. Links missing from the pasted appendix remain marked in the resource catalogue.</p><pre class="rp-source-brief">'+esc(window.REFERENCE_PACK.brief||'Source not available')+'</pre></div>';}
else if(section==='updates'){c.innerHTML='<div class="rp-notice"><h2>What was imported</h2><p>All 34 resource descriptions and use cases from the supplied appendix, plus four separate website implementations. The original Google Docs hyperlinks were absent from the pasted text. Independently identified destinations are labelled; unresolved records remain visible.</p><p>Your personal Resource board, Skills library, MCPs and My AI systems have not been merged with this collection.</p></div>'+sites.map(s=>'<details class="rp-coverage"><summary>'+esc(s.name)+' · implementation coverage</summary><pre>'+esc(JSON.stringify(s.coverage,null,2))+'</pre></details>').join('');}
else {c.innerHTML='<div class="my-toolbar"><label>'+svgIcon('search')+'<input id="rp-search" aria-label="Search reference resources" placeholder="Search tools, tutorials, MCPs…"></label><select id="rp-filter" aria-label="Resource category"><option value="">All categories</option>'+[...new Set(rs.map(x=>x.category))].map(x=>'<option>'+esc(x)+'</option>').join('')+'</select><span id="rp-count"></span></div><div class="my-grid" id="rp-results"></div>';const paint=()=>{const q=document.getElementById('rp-search').value.toLowerCase(),cat=document.getElementById('rp-filter').value,found=rs.filter(x=>(!cat||cat===x.category)&&JSON.stringify(x).toLowerCase().includes(q));document.getElementById('rp-count').textContent=found.length+' / '+rs.length;document.getElementById('rp-results').innerHTML=found.map(x=>'<button class="my-card" data-rp-resource="'+x.id+'">'+svgIcon(x.category.includes('MCP')?'plug':'code')+'<small>'+esc(x.category)+'</small><h3>'+esc(x.title)+'</h3><p>'+esc(x.description)+'</p><footer><span>'+ (x.url?'Destination identified':'Source link needed')+'</span>'+svgIcon('arrow')+'</footer></button>').join('')||'<p>No matches. Try another search.</p>';document.querySelectorAll('[data-rp-resource]').forEach(b=>b.onclick=()=>{const x=rs.find(r=>r.id===b.dataset.rpResource);myPreview(x.title,'<article class="my-document"><div class="my-kicker">'+esc(x.category)+'</div><h1>'+esc(x.title)+'</h1><p>'+esc(x.description)+'</p><h3>How to use this resource</h3><p>'+esc(x.use)+'</p><h3>Provenance</h3><p>'+esc(x.source)+'</p><p>'+esc(x.status)+'</p>'+(x.url?'<a href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">Open identified destination ↗</a>':'<p>The original link was not included in the pasted file. This record has been retained for completion.</p>')+'</article>');});};document.getElementById('rp-search').oninput=paint;document.getElementById('rp-filter').onchange=paint;paint();}
document.querySelectorAll('[data-rp-preview]').forEach(b=>b.onclick=()=>rpPreview(b.dataset.rpPreview));}
const rpRender=render;render=function(){const p=location.hash.slice(2).split('/');if(p[0]!=='reference-research')return rpRender();terminalCancel++;rpPage(p[1]||'overview');document.title=B.name+' — Reference Research';document.body.dataset.page='reference-research';document.body.classList.remove('catalogue-nav-open');document.querySelectorAll('.universal-sidebar a').forEach(a=>a.setAttribute('aria-current',a.hash===location.hash?'page':'false'));};
